glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
in vec4 v_color;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform Properties{
  float v_centerX;
  float v_centerY;
  float angle;
};
void main () {
  vec4 o = vec4(1, 1, 1, 1);
  vec2 v_c = vec2(v_centerX,v_centerY);
  vec4 color = vec4(1, 1, 1, 0);
  vec2 uv = v_uv0 - v_c;
  float PI = 3.142;
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    o.a *= texture_tmp.a;
  #else
    o *= texture_tmp;
  #endif
  #endif
  o *= v_color;
  float angle1 = atan(uv[1]/uv[0]);
  if(uv[0] < 0.0){
    angle1 += PI;
  }
  if(uv[1] < 0.0 && uv[0] > 0.0){
    angle1 += (2.0 * PI);
  }
  float v = 0.0;
  if(angle1 < 3.142){
    v = step(angle, angle1);
  }else{
    float angle2 = (3.142 - angle) * 2.0 + angle;
    v = step(angle1, angle2);
  }
  if(v < 1.0){
    o *= color;
  }
  gl_FragColor = o;
}

